package com.bank.rdd.core;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.logging.Logger;

// An immutable, partitioned, lazily-evaluated collection with lineage.
// Each transformation returns a NEW SimpleRdd; the parent is never mutated.
public class SimpleRdd<T> {
    private static final Logger log = Logger.getLogger(SimpleRdd.class.getName());

    // Partitions of the BASE data (only non-null for the root RDD).
    private final List<List<T>> basePartitions;

    // Lineage: parent + the function that derives THIS rdd from the parent.
    private final SimpleRdd<Object> parent;
    private final Function<List<Object>, List<T>> transform;

    // Root constructor: holds real data partitions, no parent.
    public SimpleRdd(List<List<T>> basePartitions) {
        this.basePartitions = basePartitions;
        this.parent = null;
        this.transform = null;
    }

    // Derived constructor: records lineage instead of data.
    @SuppressWarnings("unchecked")
    private SimpleRdd(SimpleRdd<?> parent, Function<List<Object>, List<T>> transform) {
        this.basePartitions = null;
        this.parent = (SimpleRdd<Object>) parent;
        this.transform = transform;
    }

    public int numPartitions() {
        return basePartitions != null ? basePartitions.size() : parent.numPartitions();
    }

    // Transformation: lazy. Returns a new RDD, runs nothing now.
    @SuppressWarnings("unchecked")
    public SimpleRdd<T> filter(Predicate<T> p) {
        log.fine(() -> "building lineage: filter (lazy, nothing runs yet)");
        return new SimpleRdd<>(this, in -> {
            List<T> out = new ArrayList<>();
            for (Object o : in) { T t = (T) o; if (p.test(t)) out.add(t); }
            return out;
        });
    }

    // Transformation: lazy map.
    public <R> SimpleRdd<R> map(Function<T, R> f) {
        log.fine(() -> "building lineage: map (lazy, nothing runs yet)");
        return new SimpleRdd<>(this, in -> {
            List<R> out = new ArrayList<>();
            for (Object o : in) { @SuppressWarnings("unchecked") T t = (T) o; out.add(f.apply(t)); }
            return out;
        });
    }

    // Compute ONE partition by replaying lineage from the base — pure/deterministic.
    @SuppressWarnings("unchecked")
    public List<T> computePartition(int index) {
        if (basePartitions != null) {
            return new ArrayList<>(basePartitions.get(index)); // defensive copy (immutability)
        }
        List<Object> parentData = (List<Object>) parent.computePartition(index);
        return transform.apply(parentData);
    }

    // ACTION: triggers evaluation across all partitions.
    public List<T> collect() {
        log.info(() -> "ACTION collect() triggers execution of the lineage");
        List<T> all = new ArrayList<>();
        for (int i = 0; i < numPartitions(); i++) all.addAll(computePartition(i));
        return all;
    }

    // Simulate losing a partition and recovering it from lineage.
    public List<T> recomputePartition(int index) {
        log.info(() -> "partition " + index + " lost — recomputing from lineage");
        return computePartition(index);
    }
}
