package com.bank.rdd;

import com.bank.rdd.core.SimpleRdd;
import com.bank.rdd.model.Txn;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class RddDemo {
    private static final Logger log = Logger.getLogger(RddDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new RddLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Base RDD: 2 partitions of transactions (Rajesh SAV2001, Priya CUR3001).
        List<List<Txn>> parts = List.of(
            List.of(new Txn("SAV2001", new BigDecimal("1000")),
                    new Txn("CUR3001", new BigDecimal("500"))),
            List.of(new Txn("SAV2001", new BigDecimal("3000")),
                    new Txn("CUR3001", new BigDecimal("200")))
        );
        SimpleRdd<Txn> base = new SimpleRdd<>(parts);

        // Lazy transformations: keep only Rajesh's txns, then map to amounts.
        SimpleRdd<BigDecimal> rajeshAmounts = base
            .filter(t -> t.getAccountId().equals("SAV2001"))
            .map(Txn::getAmount);

        // Action: now it runs.
        List<BigDecimal> result = rajeshAmounts.collect();
        log.info(() -> "Rajesh amounts = " + result);

        // Simulate a lost partition and recover via lineage (deterministic).
        List<BigDecimal> recovered = rajeshAmounts.recomputePartition(1);
        log.info(() -> "Recovered partition 1 = " + recovered);
    }
}

